use std::path::Path;

use serde_json::Value as JsonValue;

use crate::support::{run, run_json};

pub(crate) fn authorize_for_node(
    cwd: &Path,
    node_id: &str,
    placement: &str,
    record: &str,
    expected: Option<&str>,
) -> JsonValue {
    let mut args = vec![
        "program",
        "module",
        "foreign-process",
        "placement",
        "default-deployment",
        "authorize",
        "--slot",
        super::SLOT,
        "--node-id",
        node_id,
        "--placement-entry",
        placement,
        "--activation-record",
        record,
    ];
    if let Some(expected) = expected {
        args.extend(["--expected-head", expected]);
    }
    args.extend(["--format", "json"]);
    run_json(cwd, args)
}

pub(crate) fn rebind_placement(cwd: &Path, authorization: &str, target_node_id: &str) -> JsonValue {
    run_json(cwd, rebind_args(authorization, target_node_id))
}

pub(crate) fn rebind_placement_raw(
    cwd: &Path,
    authorization: &str,
    target_node_id: &str,
) -> std::process::Output {
    run(cwd, rebind_args(authorization, target_node_id))
}

pub(crate) fn verify_placement_rebind(cwd: &Path, receipt: &str) -> JsonValue {
    run_json(cwd, verify_args(receipt))
}

pub(crate) fn verify_placement_rebind_raw(cwd: &Path, receipt: &str) -> std::process::Output {
    run(cwd, verify_args(receipt))
}

fn rebind_args<'a>(authorization: &'a str, target_node_id: &'a str) -> Vec<&'a str> {
    vec![
        "program",
        "module",
        "foreign-process",
        "placement",
        "default-deployment",
        "rebind-placement",
        authorization,
        "--target-node-id",
        target_node_id,
        "--format",
        "json",
    ]
}

fn verify_args(receipt: &str) -> Vec<&str> {
    vec![
        "program",
        "module",
        "foreign-process",
        "placement",
        "default-deployment",
        "verify-placement-rebind",
        receipt,
        "--format",
        "json",
    ]
}

