        "unicodex.stage_verification_report.v6"
    );
    stage_report_value::assert_report_counts(&value);
    assert_verified(cwd, &typed, true);

    let forged = stage_report_value::forged_failed_count(&store, &value);
    assert_eq!(store.verify_object(&forged).status, RefStatus::Ok);
    assert_rejected(cwd, &forged, "acceptance summary replay mismatch");

    let v2 =
        stage_report_value::with_schema(&store, &value, "unicodex.stage_verification_report.v2");
    assert_verified(cwd, &v2, true);
    let legacy = stage_report_value::legacy_v1(&store, &value);
    assert_verified(cwd, &legacy, false);
    (typed, legacy)
}

